'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const icons = {
 grid: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 server: '<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M11 6.5h6M11 17.5h6"/>',
 shield: '<path d="M12 3 3.5 6v6c0 5 8.5 9 8.5 9s8.5-4 8.5-9V6L12 3Z"/><path d="m8 12 3 3 5-6"/>',
 rules: '<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',
 list: '<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8M8 12h8M8 17h5"/>',
 settings: '<path d="m10 3-.6 2-2 .9-2-.5L3 9l1.5 1.5v3L3 15l2.4 3.6 2-.5 2 .9.6 2h4l.6-2 2-.9 2 .5L21 15l-1.5-1.5v-3L21 9l-2.4-3.6-2 .5-2-.9L14 3Z"/><circle cx="12" cy="12" r="3"/>',
 activity: '<path d="M2 12h4l3-8 5 16 3-8h5"/>',
 block: '<circle cx="12" cy="12" r="9"/><path d="m6 6 12 12"/>',
 plus: '<path d="M12 5v14M5 12h14"/>',
 arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
 download: '<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
 clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'
};
const icon = (name) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.shield}</svg>`;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = n => new Intl.NumberFormat('en-US').format(n || 0);
const time = v => new Date(v).toLocaleTimeString('en-US', {hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
const names = {overview:'Overview',routes:'Proxy Hosts',security:'WAF protection',rules:'Custom rules',events:'Events',users:'Users',oidc:'OIDC',tls:'Certificates',settings:'Settings'};
const owaspNames = {A01:'Broken Access Control',A02:'Security Misconfiguration',A03:'Software Supply Chain Failures',A04:'Cryptographic Failures',A05:'Injection',A06:'Insecure Design',A07:'Authentication Failures',A08:'Software or Data Integrity Failures',A09:'Security Logging and Alerting Failures',A10:'Mishandling of Exceptional Conditions'};
const state = {config:null,status:null,analytics:null,upstreams:[],events:[],sessions:[],users:[],oidc:null,tls:null,csrf:'',page:'overview',query:'',action:'',ready:false,busy:false,polling:false,revision:null,analyticsExpanded:false};
let toastTimer, searchTimer;
function setTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('bastion-theme',theme);const button=$('#theme-toggle');if(button){button.textContent=theme==='dark'?'Light mode':'Dark mode';button.setAttribute('aria-label',theme==='dark'?'Switch to light theme':'Switch to dark theme');}}
function initTheme(){const saved=localStorage.getItem('bastion-theme');setTheme(saved==='light'?'light':'dark');$('#theme-toggle').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));}
initTheme();
function toast(message, error=false) { const el=$('#toast'); el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5500); }
async function api(path, options={}) {
 const headers = {...options.headers};
 if(options.body){headers['Content-Type']='application/json'; options.body=JSON.stringify(options.body);}
 if(options.method && options.method!=='GET') headers['X-CSRF-Token']=state.csrf;
 const res=await fetch(path,{...options,headers,credentials:'same-origin'});
 const raw=await res.text();
 let data={};
 if(raw.trim()){try{data=JSON.parse(raw);}catch{let detail=raw.trim().replace(/\s+/g,' ').slice(0,160);if(raw.includes('<')){const doc=new DOMParser().parseFromString(raw,'text/html');detail=(doc.querySelector('title')?.textContent||doc.body?.textContent||detail).replace(/\s+/g,' ').trim().slice(0,160);}throw new Error(res.ok?'The gateway returned an invalid response':`HTTP ${res.status}: ${detail}`);}}
 if(!res.ok){if(res.status===401 && path!=='/api/login')showLogin();throw new Error(data.error||`HTTP ${res.status}`);}
 return data;
}
function showLogin(){state.ready=false;state.csrf='';$('#shell').hidden=true;$('#login').hidden=false;$('#password').value='';}
async function start(){const [config,status,analytics,upstreams,events,sessions]=await Promise.all([api('/api/config'),api('/api/status'),api('/api/analytics'),api('/api/upstreams'),api('/api/events'),api('/api/sessions')]);Object.assign(state,{config,status,analytics,upstreams,events,sessions,ready:true});$('#login').hidden=true;$('#shell').hidden=false;navigate();}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const btn=$('button',e.target);btn.disabled=true;$('#login-error').textContent='';try{const s=await api('/api/login',{method:'POST',body:{username:$('#username').value.trim(),password:$('#password').value}});state.csrf=s.csrf;$('#username').value='';$('#password').value='';await start();}catch(err){$('#login-error').textContent=err.message;}finally{btn.disabled=false;}});
$('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST'});showLogin();}catch(e){toast(e.message,true);}});
function nav(){const order=['grid','server','shield','rules','list','settings','shield','settings','settings'];$('#nav').innerHTML=Object.entries(names).map(([key,label],i)=>`<a href="#${key}" class="nav-item ${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''} title="${label}">${icon(order[i])}<span>${label}</span>${key==='routes'?`<span class="nav-count">${state.config.routes.length}</span>`:''}</a>`).join('');$('#crumb').textContent=names[state.page];}
async function navigate(){
 if(!state.ready)return;
 const page=Object.hasOwn(names,location.hash.slice(1))?location.hash.slice(1):'overview';
 state.page=page;nav();render();
 try{const endpoint={users:'/api/users',oidc:'/api/oidc',tls:'/api/tls'}[page];if(endpoint){const value=await api(endpoint);state[page]=value;if(state.ready&&state.page===page)render();}}catch(err){toast(err.message,true);}
}

window.addEventListener('hashchange',navigate);
function head(title,description,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`;}
function badge(action){const map={allowed:['Forwarded',''],blocked:['Blocked','red'],detected:['Detected','amber'],error:['Error','red']};const [label,color]=map[action]||[action,'gray'];return `<span class="badge ${color}">${esc(label)}</span>`;}
function empty(title,description,button=''){return `<div class="empty"><div class="empty-icon">${icon('server')}</div><h3>${title}</h3><div>${description}</div>${button}</div>`;}
function eventTable(events,compact=false){if(!events.length)return empty('No events yet','Events will appear here as requests reach the gateway.');return `<div class="table-wrap"><table><thead><tr><th>TIME</th><th>REQUEST</th><th>CLIENT-IP</th><th>RESULT</th>${compact?'':'<th>STATUS / DURATION</th>'}<th>RULE / REASON</th></tr></thead><tbody>${events.map(e=>`<tr class="event-row ${e.action==='blocked'?'event-blocked':''}" tabindex="0" role="button" data-event="${esc(e.id)}" aria-label="Open event ${esc(e.id)}"><td class="mono">${time(e.time)}</td><td><strong>${esc(e.host)}</strong><small class="mono">${esc(e.method)} ${esc(e.path.length>45?e.path.slice(0,45)+'…':e.path)}</small></td><td class="mono">${esc(e.client)}</td><td>${badge(e.action)}</td>${compact?'':`<td class="mono">${e.status}<small>${number(Math.round(e.duration))} ms</small></td>`}<td>${e.ruleIds.length?`<span class="mono">${e.ruleIds.slice(0,2).join(', ')}</span>`:esc(e.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`;}
function trafficChart(){const series=state.status.series||[];const max=Math.max(5,...series.map(b=>b.requests));const x=i=>42+i*650/59,y=v=>160-v/max*135;const points=field=>series.map((b,i)=>`${x(i)},${y(b[field])}`).join(' ');return `<svg viewBox="0 0 715 195" role="img" aria-label="Requests and blocks in the last 60 minutes"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#29b296" stop-opacity=".15"/><stop offset="100%" stop-color="#29b296" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(n=>`<line class="grid" x1="42" x2="692" y1="${y(max*n)}" y2="${y(max*n)}"/><text x="30" y="${y(max*n)+3}" text-anchor="end">${Math.round(max*n)}</text>`).join('')}<polygon points="42,160 ${points('requests')} 692,160" fill="url(#fill)"/><polyline class="line" points="${points('requests')}"/><polyline class="blocked-line" points="${points('blocked')}"/>${[0,15,30,45,59].map(i=>`<text x="${x(i)}" y="186" text-anchor="middle">${series[i]?new Date(series[i].minute*60000).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}):''}</text>`).join('')}</svg>`;}
function analyticsPanel(){const routes=Object.entries(state.analytics?.routes||{}).sort((a,b)=>b[1]-a[1]).slice(0,5);const statuses=Object.entries(state.analytics?.statuses||{}).sort((a,b)=>a[0].localeCompare(b[0]));return `<section class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Traffic by proxy host</h2><div class="panel-sub">Requests retained in the analytics window</div></div></div><div class="health-list">${routes.length?routes.map(([name,count])=>`<div class="health-row"><span>${esc(name||'Unmatched')}</span><strong>${number(count)}</strong></div>`).join(''):'<div class="empty">No route traffic recorded yet.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Response distribution</h2><div class="panel-sub">HTTP status families</div></div></div><div class="health-list">${statuses.length?statuses.map(([status,count])=>`<div class="health-row"><span>${esc(status)}</span><strong>${number(count)}</strong></div>`).join(''):'<div class="empty">No responses recorded yet.</div>'}</div></section></section>`;}
function overview(){
 const c=state.config,s=state.status,active=c.routes.filter(r=>r.enabled).length;
 return head('<span class="eyebrow">PERIMETER CONTROL</span>Hold the perimeter.','One gateway. Every request inspected.',`<a class="secondary" href="#events">${icon('list')} Events</a><button class="primary" data-add-route>${icon('plus')} Add proxy host</button>`)+`
 <div class="protection-banner ${c.mode==='detection'?'warning':''}"><div class="banner-icon">${icon('shield')}</div><div><h3>${c.mode==='blocking'?'WAF enforcement active':'Detection mode active'}</h3><p>${c.mode==='blocking'?`OWASP Core Rule Set · Paranoia level ${c.paranoia} · ${active} active proxy hosts`:'Rule matches are logged. WAF rules do not block attacks.'}</p></div><span class="badge">${c.mode==='blocking'?'Blocking mode':'Detection only'}</span></div>
 <div class="stats">${[['Total requests',number(s.requests),'Since last start','activity',''],['Blocked requests',number(s.blocked),`${s.requests?(s.blocked/s.requests*100).toFixed(1):'0'}% of all requests`,'shield','red'],['Active proxy hosts',`${active}<span class="stat-note"> / ${c.routes.length}</span>`,'Configured routes','server','']].map(([label,value,note,i,color])=>`<div class="stat ${color?'threat-stat':''}"><div class="stat-top">${label}${icon(i)}</div><div class="stat-value ${color}">${value}</div><div class="stat-note">${note}</div></div>`).join('')}</div>
 <section class="panel traffic-panel"><div class="panel-head"><div><h2>Traffic overview</h2><div class="panel-sub">Requests per minute · last 60 minutes</div></div><div class="legend"><span><i></i> Requests</span><span><i class="red"></i> Blocked</span></div></div><div class="chart">${trafficChart()}</div><div class="gateway-strip"><span>ENGINE <strong>Coraza / OWASP CRS</strong></span><span>RATE LIMIT <strong>${number(c.rateLimit)} / min / IP</strong></span><span>UPTIME <strong>${uptime(s.uptimeSeconds)}</strong></span></div></section>
 <section class="panel"><div class="panel-head table-heading"><div><h2>Recent events</h2><div class="panel-sub">Live activity from your gateway</div></div><a class="text-link" href="#events">View all events →</a></div>${eventTable(state.events.slice(0,6),true)}</section>
 <details id="analytics-details" class="analytics-disclosure" ${state.analyticsExpanded?'open':''}><summary>Traffic breakdown &amp; gateway details</summary>${analyticsPanel()}<div class="health-foot">Detected requests: <strong>${number(s.detected)}</strong> · Forwarded with a rule match. ${s.auditError?esc(s.auditError):'Configuration is applied without a restart.'}</div></details>
 ${!active?'<p class="bottom-note">Add your first proxy host to connect an application.</p>':''}`;
}
function uptime(seconds){if(seconds<60)return `${seconds} s`;if(seconds<3600)return `${Math.floor(seconds/60)} min`;return `${Math.floor(seconds/3600)} h ${Math.floor(seconds%3600/60)} min`;}
function routePolicySummary(r){const parts=[];if(r.wafMode&&r.wafMode!=='inherit')parts.push('WAF '+r.wafMode);if(r.rateLimit)parts.push(r.rateLimit+'/min');if(r.maxBodyBytes)parts.push(Math.round(r.maxBodyBytes/1024)+' KiB');if(r.allowedMethods?.length)parts.push(r.allowedMethods.join('/'));if(r.allowedContentTypes?.length)parts.push('Content-Type allowlist');if(r.securityHeaders)parts.push('Security headers');return parts.length?`<small class="route-policy">${esc(parts.join(' · '))}</small>`:'';} function routes(){const rs=state.config.routes;return head('Proxy Hosts','Connect your domains to your applications. WAF protection runs alongside them.',`<button class="primary" data-add-route>${icon('plus')} Add proxy host</button>`)+`<section class="panel"><div class="panel-head table-heading"><div><h2>Your applications</h2><div class="panel-sub">${rs.length} hosts configured · longest matching path wins</div></div><span class="badge gray">HTTP / HTTPS / WebSocket</span></div>${rs.length?`<div class="table-wrap"><table><thead><tr><th>APPLICATION / DOMAIN</th><th>UPSTREAM</th><th>PATH</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${rs.map(r=>{const checks=state.upstreams.filter(u=>u.route===r.id),checked=checks.some(u=>u.lastCheck),healthy=checked&&checks.some(u=>u.healthy),failed=checks.reduce((n,u)=>n+(u.failureCount||0),0);return `<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.host)}</small></td><td class="mono">${esc(r.upstreams[0])}${r.upstreams.length>1?`<small>+ ${r.upstreams.length-1} more · round robin</small>`:''}</td><td class="mono">${esc(r.path)}${routePolicySummary(r)}</td><td><span class="badge ${!r.enabled?'gray':!checked?'amber':healthy?'':'red'}">${!r.enabled?'Paused':!checked?'No runtime data':healthy?(failed?`Healthy · ${failed} recent failures`:'Healthy'):'Cooling down'}</span></td><td><div class="row-actions"><button class="secondary" data-edit-route="${esc(r.id)}">Edit</button><button class="secondary" data-toggle-route="${esc(r.id)}">${r.enabled?'Pause':'Enable'}</button><button class="danger" data-delete-route="${esc(r.id)}">Delete</button></div></td></tr>`}).join('')}</tbody></table></div>`:empty('Your first application is waiting.','Enter a domain and backend – Bastion handles routing and inspection.',`<button class="primary" data-add-route>${icon('plus')} Add first host</button>`)}</section><p class="bottom-note">Targets are selected round-robin while healthy. Transport failures and 502/503/504 responses temporarily cool down the selected target; no request bodies are retried.</p>`;}
function owaspCoverage(){const c=state.config;const controls={A01:c.routes.some(r=>r.allowedMethods?.length||r.botDenyPatterns?.length)||c.allowCIDRs.length>0,A02:c.mode==='blocking'&&c.maxBodyBytes>0||c.routes.some(r=>r.securityHeaders),A03:true,A04:c.responseInspection||c.routes.some(r=>r.upstreams.some(u=>u.startsWith('https://'))),A05:true,A06:c.rateLimit>0,A07:c.routes.some(r=>r.allowedMethods?.length)||c.rules.some(r=>r.category==='A07'),A08:c.routes.some(r=>r.upstreams.length>0),A09:true,A10:c.maxBodyBytes>0}; return `<section class="panel owasp-panel"><div class="panel-head"><div><h2>OWASP Top 10:2025 coverage</h2><div class="panel-sub">Gateway controls and CRS coverage mapped to the current OWASP awareness categories.</div></div><a class="text-link" href="https://top10.owasp.org/2025/" target="_blank" rel="noreferrer">Reference ↗</a></div><div class="owasp-grid">${Object.entries(owaspNames).map(([id,name])=>`<div class="owasp-item"><span class="owasp-id">${id}</span><div><strong>${esc(name)}</strong><small>${controls[id]?'Control active or inherited':'Add a route control or custom rule'}</small></div><span class="badge ${controls[id]?'':'amber'}">${controls[id]?'Covered':'Review'}</span></div>`).join('')}</div><p class="field-help">Coverage is a configuration aid, not a certification. CRS remains authoritative for A05 Injection, while TLS, access control, limits, sessions, logging, and upstream validation address the surrounding gateway risks.</p></section>`;}
function security(){const c=state.config;return head('Protection policy','Control the rule set, access control, and request limits.')+owaspCoverage()+`<form id="security-form" class="settings-grid"><section class="panel form-panel"><h2>OWASP Core Rule Set</h2><p>Detects, among other things, SQL Injection, Cross-Site Scripting, Path Traversal and Command Injection.</p><div class="field"><label for="mode">Operating mode</label><select id="mode" name="mode"><option value="blocking" ${c.mode==='blocking'?'selected':''}>Block · reject attacks</option><option value="detection" ${c.mode==='detection'?'selected':''}>Detect · log only</option></select><p class="field-help">Detection mode is useful for tuning rules. IP and size limits remain active.</p></div><div class="form-grid"><div class="field"><label for="paranoia">Paranoia Level</label><select id="paranoia" name="paranoia">${[1,2,3,4].map(n=>`<option value="${n}" ${c.paranoia===n?'selected':''}>Level ${n}${n===1?' · recommended to start':''}</option>`).join('')}</select></div><div class="field"><label for="threshold">Anomaly threshold</label><input id="threshold" name="threshold" type="number" min="1" max="100" required value="${c.threshold}"></div></div><div class="info">Higher paranoia levels enable stricter rules and may affect legitimate requests. Individual CRS rules can be excluded per proxy host.</div><div class="separator"></div><h2>Traffic limits</h2><p>Limits apply per client IP and route. Directly connected client IPs are used.</p><div class="form-grid"><div class="field"><label for="rateLimit">Requests per minute</label><input id="rateLimit" name="rateLimit" type="number" min="1" max="100000" required value="${c.rateLimit}"></div><div class="field"><label for="maxBodyBytes">Maximum body size (KiB)</label><input id="maxBodyBytes" name="maxBodyKiB" type="number" min="1" max="32768" required value="${c.maxBodyBytes/1024}"></div></div><label class="check"><input type="checkbox" name="responseInspection" ${c.responseInspection?'checked':''}> Inspect response bodies too</label><p class="field-help">Buffers inspectable text responses up to 1 MiB. Larger or compressed text responses are rejected with 502. Leave disabled for streaming.</p><div class="separator"></div><button class="primary" type="submit">Save protection settings</button></section><section class="panel form-panel"><h2>IP access control</h2><p>One IPv4 or IPv6 CIDR per line. Deny rules always take precedence.</p><div class="field"><label for="denyCIDRs">Blocked networks</label><textarea id="denyCIDRs" name="denyCIDRs" rows="5" placeholder="192.0.2.10/32&#10;2001:db8::/32">${esc(c.denyCIDRs.join('\n'))}</textarea></div><div class="field"><label for="allowCIDRs">Restrict access to these networks</label><textarea id="allowCIDRs" name="allowCIDRs" rows="5" placeholder="Empty = everyone except blocked IPs">${esc(c.allowCIDRs.join('\n'))}</textarea><p class="field-help">A non-empty list excludes all other clients. Allowed IPs still pass through WAF inspection.</p></div><div class="info warning">This access control applies to your applications. Admin access is secured separately through Docker port binding.</div></section></form>`;}
function rules(){return head('Custom rules','Extend the OWASP rule set with targeted filters for your applications.',`<button class="primary" data-add-rule>${icon('plus')} Create rule</button>`)+`<div class="info">Custom rules can inspect the path, query string, headers, body, User-Agent, or method using bounded literal matching. Assigning an OWASP Top 10:2025 category makes the control visible in your coverage view. Block rules only log in detection mode; OWASP CRS remains responsible for full attack detection.</div><div class="separator"></div>${state.config.rules.length?state.config.rules.map(r=>`<article class="rule-card"><span class="rule-symbol">${icon('rules')}</span><div class="rule-content"><h3>${esc(r.name)}</h3><p>${r.category?`<span class="badge gray">${esc(r.category)} · ${esc(owaspNames[r.category]||'OWASP')}</span> `:''}<span class="mono">${esc(r.field)}</span> contains <span class="mono">${esc(r.value)}</span></p></div><span class="badge ${r.enabled?(r.action==='block'?'red':'amber'):'gray'}">${r.enabled?(r.action==='block'?'Block':'Log'):'Paused'}</span><div class="row-actions"><button class="secondary" data-edit-rule="${esc(r.id)}">Edit</button><button class="danger" data-delete-rule="${esc(r.id)}">Delete</button></div></article>`).join(''):`<section class="panel">${empty('Room for your custom rules.','The OWASP Core Rule Set is already active independently.',`<button class="primary" data-add-rule>${icon('plus')} Create first rule</button>`)}</section>`}`;}
function events(){return head('Request events','The last 1,000 requests since startup. New events appear automatically.',`<a class="secondary" href="/api/events?download=1" download>${icon('download')} Export JSON</a>`)+`<div class="toolbar"><input id="event-search" type="search" placeholder="Search IP, domain, path, or request ID …" value="${esc(state.query)}" aria-label="Search events"><select id="event-filter" aria-label="Filter results"><option value="">All results</option>${Object.entries({blocked:'Blocked',detected:'Detected',allowed:'Forwarded',error:'Error'}).map(([v,l])=>`<option value="${v}" ${state.action===v?'selected':''}>${l}</option>`).join('')}</select><span id="event-count" class="count"></span></div><section class="panel" id="event-table"></section><p class="bottom-note">Query strings, request bodies, and credentials are not stored. JSONL files in the data directory rotate at 10 MiB.</p>`;}
function filteredEvents(){return state.events.filter(e=>(!state.action||e.action===state.action)&&(!state.query||`${e.host} ${e.path} ${e.client} ${e.reason} ${e.id}`.toLowerCase().includes(state.query.toLowerCase())));}
function updateEventTable(){if(state.page!=='events'||!$('#event-table'))return;const filtered=filteredEvents();$('#event-table').innerHTML=eventTable(filtered);$('#event-count').textContent=`${number(filtered.length)} Events`;}
function sessionTime(v){return new Date(v).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'});}
function sessionPanel(){const sessions=state.sessions||[];return `<section class="panel form-panel"><div class="panel-head table-heading"><div><h2>Security & sessions</h2><div class="panel-sub">Sessions expire after 30 minutes idle or 8 hours absolute.</div></div><button class="danger" id="revoke-sessions" ${sessions.length?'':'disabled'}>Revoke all sessions</button></div>${sessions.length?`<div class="table-wrap"><table><thead><tr><th>CLIENT</th><th>CREATED</th><th>LAST ACTIVITY</th><th>EXPIRES</th><th>STATUS</th></tr></thead><tbody>${sessions.map(s=>`<tr><td class="mono">${esc(s.client||'Unknown')}</td><td>${esc(sessionTime(s.created))}</td><td>${esc(sessionTime(s.lastSeen))}</td><td>${esc(sessionTime(s.expires))}</td><td><span class="badge ${s.current?'':'gray'}">${s.current?'Current session':'Active'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('No active sessions','Sign in again to create a new administrator session.')}<p class="field-help">Revoking sessions immediately signs out every administrator browser, including this one.</p></section>`;}
function settings(){return head('Gateway settings','Operations, security, and integration.')+`<div class="settings-grid"><section class="panel form-panel"><h2>Back up configuration</h2><p>Export routes, WAF settings, IP filters, and custom rules. Passwords and certificates are not included.</p><button class="secondary" id="export-config">${icon('download')} Export configuration</button><div class="separator"></div><h2>Restore configuration</h2><p>The import replaces the current configuration after validation. Existing connections continue using their current configuration.</p><label for="import-config">Bastion configuration (.json)</label><input type="file" id="import-config" accept="application/json,.json"><p class="field-help">A summary is shown for confirmation before import.</p><div class="separator"></div><h2>Your instance</h2><div class="health-list">${[['Version','0.1 · initial release'],['Engine',state.status.engine],['Configuration revision',state.config.revision],['Current uptime',uptime(state.status.uptimeSeconds)],['Response inspection',state.config.responseInspection?'Active':'Disabled'],['Active upstream checks',state.status.upstreamHealthIntervalSeconds+'s interval'],['Health alerts',state.status.upstreamAlerts?'Webhook enabled':'Disabled']].map(([k,v])=>`<div class="health-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div></section><section class="panel form-panel"><h2>TLS & certificates</h2><p>Manage uploads and automatic issuance on the <a href="#tls">Certificates</a> page. Changes require a process restart.</p><div class="info"><strong>Automatic certificates</strong><br>Choose HTTP-01 or Cloudflare DNS-01 on the Certificates page and follow the setup instructions.<br><br><strong>Your own certificate</strong><br>Choose manual mode, upload the PEM certificate and key, save, then restart Bastion. Existing environment settings are used until GUI settings are saved.</div><div class="separator"></div><h2>Monitoring</h2><p>Prometheus metrics are available on the admin listener at <code>/metrics</code> Use a dedicated BASTION_METRICS_TOKEN bearer token; never reuse the admin password.</p><div class="info">IP-based limits require Bastion to see the client directly. Upstream CDNs and proxies are not treated as trusted sources in this version.</div></section></div><div class="separator"></div>${sessionPanel()}`;}function users(){
 const create=`<section class="panel form-panel"><h2>Create a local user</h2><p>Local users sign in with a username and password. Changes take effect immediately.</p><form id="local-user-form">
 <div class="form-grid"><div class="field"><label for="new-username">Username</label><input id="new-username" name="username" autocomplete="off" placeholder="e.g. alex" minlength="3" required></div><div class="field"><label for="new-password">Password</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="12" required aria-describedby="new-password-help"><p id="new-password-help" class="field-help">Use at least 12 characters.</p></div></div>
 <div class="field"><label for="new-role">Access level</label><select id="new-role" name="role"><option value="viewer">Viewer · read-only access</option><option value="admin">Admin · manage configuration and users</option></select></div>
 <p class="form-error" role="alert" data-form-error></p><div class="form-actions"><button class="primary" type="submit">Create user</button></div></form></section>`;
 const list=state.users.length?`<div class="table-wrap"><table class="users-table"><thead><tr><th>IDENTITY</th><th>SOURCE</th><th>ACCESS LEVEL</th><th>LAST LOGIN</th><th>ACTIONS</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name||u.subject)}</strong><small class="mono">${esc(u.email||u.subject)}</small></td><td><span class="badge gray">${esc(u.source)}</span></td><td><select class="user-role" aria-label="Access level for ${esc(u.name||u.subject)}" data-subject="${esc(u.subject)}" data-role="${esc(u.role)}"><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option><option value="viewer" ${u.role==='viewer'?'selected':''}>Viewer</option></select></td><td>${u.lastLogin?esc(sessionTime(u.lastLogin)):'Not signed in yet'}</td><td><div class="row-actions">${u.source==='local'?`<button class="secondary password-user" data-subject="${esc(u.subject)}">Change password</button>`:''}<button class="danger revoke-user" data-subject="${esc(u.subject)}">Delete user</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No managed users yet','Create a local user above, or configure OIDC for identity-provider sign-in. The global administrator password is managed separately.');
 return head('Users','Manage who can access Bastion.',`<a class="secondary" href="#oidc">Set up OIDC login →</a>`)+`<div class="page-stack">${create}<section class="panel"><div class="panel-head table-heading"><div><h2>Managed users</h2><p class="panel-sub">Role changes save immediately. Password changes and deletion end the user’s sessions.</p></div><span class="badge gray">${state.users.length} users</span></div>${list}</section></div>`;
}
function restartNotice(){return `<div class="info warning restart-note"><strong>Save, then restart Bastion</strong><p>These settings are applied when the service starts. Saving does not change the running service. Restart Bastion using your deployment tools after completing the setup.</p></div>`;}
function oidc(){
 const s=state.oidc||{};
 return head('OIDC','Configure identity-provider login. Saved changes require a process restart.')+restartNotice()+`<section class="panel form-panel setup-panel"><h2>1. Connect your identity provider</h2><p>Create an OIDC client in your provider, then copy its issuer URL, client ID and secret here. Register the exact callback URI below in that client.</p><form id="oidc-form">
 <div class="field"><label for="oidc-issuer">Issuer URL</label><input id="oidc-issuer" name="issuer" type="url" value="${esc(s.issuer)}"></div>
 <div class="field"><label for="oidc-client">Client ID</label><input id="oidc-client" name="clientId" value="${esc(s.clientId)}"></div>
 <div class="field"><label for="oidc-secret">Client secret</label><input id="oidc-secret" name="clientSecret" type="password" autocomplete="new-password"><p class="field-help">${s.secretConfigured?'A secret is configured. Leave blank to retain it.':'No secret configured.'}</p></div>
 <div class="field"><label for="oidc-redirect">Redirect URI</label><input id="oidc-redirect" name="redirectUri" type="url" value="${esc(s.redirectUri)}" placeholder="https://bastion.example.com/oauth2/callback"><p class="field-help">Use your Bastion administration address followed by /oauth2/callback. It must match the redirect URI registered with your provider.</p></div>
 <div class="field"><label for="oidc-role">Role claim</label><input id="oidc-role" name="roleClaim" value="${esc(s.roleClaim||'role')}"></div>
 <h2 class="section-heading">2. Choose where to use OIDC</h2><p class="field-help">Keep password login available while testing your provider. Proxy login only applies to hosts explicitly marked as OIDC protected.</p><label class="check"><input type="checkbox" name="adminEnabled" ${s.adminEnabled?'checked':''}> Enable administrator OIDC login</label>
 <label class="check"><input type="checkbox" name="proxyEnabled" ${s.proxyEnabled?'checked':''}> Enable OIDC for protected proxy hosts</label>
 <p class="form-error" role="alert" data-form-error></p><div class="form-actions"><button class="primary" type="submit" ${state.oidc?'':'disabled'}>Save OIDC settings</button><span class="field-help">Restart required after saving</span></div></form></section>`;
}
function tls(){
 const s=state.tls||{},c=s.certificate||{};
 return head('Certificates','Manage TLS certificates and automatic issuance. Saved changes require a process restart.')+restartNotice()+`<div class="page-stack setup-panel"><section class="panel form-panel"><h2>1. Choose how to obtain a certificate</h2><p>Use automatic renewal with Let’s Encrypt, or upload a certificate and its matching private key.</p><form id="tls-form">
 <div class="field"><label for="tls-mode">TLS mode</label><select id="tls-mode" name="mode">${[['manual','Manual certificate'],['http01',"Let’s Encrypt · HTTP-01"],['dns01',"Let’s Encrypt · Cloudflare DNS-01"]].map(([v,label])=>`<option value="${v}" ${s.mode===v?'selected':''}>${label}</option>`).join('')}</select></div>
 <p id="tls-mode-help" class="info mode-help"></p><div class="field" data-tls-acme><label for="tls-email">ACME email</label><input id="tls-email" name="email" type="email" value="${esc(s.email)}"></div>
 <div class="field" data-tls-dns><label for="tls-domains">DNS-01 domains (comma separated)</label><input id="tls-domains" name="domains" value="${esc((s.domains||[]).join(', '))}"></div>
 <div class="field" data-tls-dns><label for="tls-token">Cloudflare API token</label><input id="tls-token" name="dnsToken" type="password" autocomplete="new-password"><p class="field-help">${s.dnsTokenConfigured?'A token is configured. Leave blank to retain it.':'DNS-01 requires a token with DNS edit access.'}</p></div>
 <p class="form-error" role="alert" data-form-error></p></form></section>
 <section class="panel form-panel" id="manual-certificate"><h2>2. Upload your manual certificate</h2><p id="cert-status">${c.present?`${esc(c.subject||'Certificate')} · ${c.expired?'Expired':'Expires'} ${esc(sessionTime(c.notAfter))} (${esc(c.source)})`:'No manual certificate available.'}</p>
 <form id="cert-upload"><div class="field"><label for="cert-file">Certificate chain (PEM)</label><input id="cert-file" name="certificate" type="file" accept=".pem,.crt" required></div>
 <div class="field"><label for="key-file">Private key (PEM)</label><input id="key-file" name="key" type="file" accept=".pem,.key" required></div><p class="form-error" role="alert" data-form-error></p><div class="form-actions"><button class="primary" type="submit">Upload certificate</button></div></form><p class="field-help">The upload stores your files. Continue with Save TLS settings below.</p></section><section class="panel form-panel"><h2>Save and apply</h2><p>Save your selected mode, then restart Bastion to activate it.</p><div class="form-actions"><button class="primary" type="submit" form="tls-form" ${state.tls?'':'disabled'}>Save TLS settings</button><span class="field-help">Restart required after saving</span></div></section></div>`;
}
function render(){const pages={overview,routes,security,rules,events,users,oidc,tls,settings};$('#main').innerHTML=pages[state.page]();updateEventTable();bindPage();}
async function saveConfig(next){if(state.busy)throw new Error('A save operation is already in progress.');state.busy=true;try{state.config=await api('/api/config',{method:'PUT',headers:{'If-Match':String(state.config.revision)},body:next});nav();toast('Configuration saved and activated.');}finally{state.busy=false;}}
function clone(){return structuredClone(state.config);}
function lines(v){return String(v).split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);}
function bindForm(selector,submit){
 const form=$(selector);if(!form)return;
 form.addEventListener('submit',async e=>{e.preventDefault();const button=$('[type=submit]',form)||$(`[type=submit][form="${form.id}"]`),error=$('[data-form-error]',form);if(button.disabled)return;button.disabled=true;error.textContent='';form.setAttribute('aria-busy','true');try{await submit(form,new FormData(form));}catch(err){error.textContent=err.message;error.setAttribute('tabindex','-1');error.focus();}finally{button.disabled=false;form.removeAttribute('aria-busy');}});
}
function bindPage(){
 if(state.page==='users'){
  bindForm('#local-user-form',async(form,f)=>{await api('/api/users',{method:'POST',body:{username:f.get('username'),password:f.get('password'),role:f.get('role')}});state.users=await api('/api/users');if(state.page==='users')render();toast('User created. They can now sign in.');});
  $$('.password-user').forEach(el=>el.addEventListener('click',()=>openDialog('Change password',`<p class="field-help">This immediately signs out the user’s active sessions.</p><div class="field"><label for="replacement-password">New password</label><input id="replacement-password" name="password" type="password" autocomplete="new-password" minlength="12" required><p class="field-help">At least 12 characters.</p></div>`,async f=>{await api('/api/users/'+encodeURIComponent(el.dataset.subject)+'/password',{method:'POST',body:{password:f.get('password')}});toast('Password changed; sessions ended.');},'Change password')));
  $$('.user-role').forEach(el=>el.addEventListener('change',async()=>{el.disabled=true;try{await api('/api/users/'+encodeURIComponent(el.dataset.subject)+'/role',{method:'PATCH',body:{role:el.value}});el.dataset.role=el.value;const u=state.users.find(u=>u.subject===el.dataset.subject);if(u)u.role=el.value;toast('Access level saved.');}catch(err){el.value=el.dataset.role;toast(err.message,true);}finally{el.disabled=false;}}));
  $$('.revoke-user').forEach(el=>el.addEventListener('click',()=>openDialog('Delete user?',`<p>Delete <strong>${esc(el.dataset.subject)}</strong> and end their sessions?</p><p class="field-help">Local users must be created again to regain access. OIDC users may return on their next provider login; revoke access at the provider to block them permanently.</p>`,async()=>{await api('/api/users/'+encodeURIComponent(el.dataset.subject),{method:'DELETE'});state.users=await api('/api/users');toast('User deleted.');},'Delete user')));
 }
 if(state.page==='oidc')bindForm('#oidc-form',async(form,f)=>{state.oidc=await api('/api/oidc',{method:'PUT',body:{issuer:f.get('issuer'),clientId:f.get('clientId'),clientSecret:f.get('clientSecret'),redirectUri:f.get('redirectUri'),roleClaim:f.get('roleClaim'),adminEnabled:f.has('adminEnabled'),proxyEnabled:f.has('proxyEnabled')}});if(state.page==='oidc')render();toast('OIDC saved. Restart Bastion to apply.');});
 if(state.page==='tls'){
  const updateMode=()=>{const mode=$('#tls-mode').value;$$('[data-tls-acme]').forEach(el=>el.hidden=mode==='manual');$$('[data-tls-dns]').forEach(el=>el.hidden=mode!=='dns01');$('#tls-email').disabled=mode==='manual';$('#tls-email').required=mode!=='manual';for(const id of ['#tls-domains','#tls-token']){$(id).disabled=mode!=='dns01';$(id).required=mode==='dns01'&&(id==='#tls-domains'||!state.tls?.dnsTokenConfigured);}$('#manual-certificate').hidden=mode!=='manual';$('#tls-mode-help').textContent={manual:'Upload the certificate and key below first. Then save these settings and restart Bastion.',http01:'Point your proxy-host domains to Bastion and allow public traffic on ports 80 and 443. Save, then restart. Certificates are issued automatically for enabled proxy hosts.',dns01:'Enter your email, domains and a Cloudflare token with DNS edit access. Save, then restart. DNS-01 also supports wildcard domains.'}[mode];};
  $('#tls-mode').addEventListener('change',updateMode);updateMode();
  bindForm('#tls-form',async(form,f)=>{state.tls=await api('/api/tls',{method:'PUT',body:{mode:f.get('mode'),email:f.get('email')||'',domains:f.get('domains')||'',dnsProvider:f.get('mode')==='dns01'?'cloudflare':'',dnsToken:f.get('dnsToken')||''}});if(state.page==='tls')render();toast('TLS settings saved. Restart Bastion to apply.');});
  bindForm('#cert-upload',async(form)=>{const res=await fetch('/api/tls/upload',{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{'X-CSRF-Token':state.csrf}});if(!res.ok)throw new Error((await res.json()).error||'Upload failed');const certificate=await res.json();if(state.tls)state.tls.certificate=certificate;if(form.isConnected){$('#cert-status').textContent=`Uploaded successfully. Expires ${sessionTime(certificate.notAfter)}. Next: save manual TLS settings below, then restart Bastion.`;form.reset();}toast('Certificate uploaded. Save manual TLS settings next.');});
 }
 if($("#analytics-details"))$("#analytics-details").addEventListener("toggle",e=>{state.analyticsExpanded=e.target.open;});
 if($('#revoke-sessions'))$('#revoke-sessions').addEventListener('click',async e=>{if(!confirm('Revoke every active administrator session? You will be signed out.'))return;e.target.disabled=true;try{await api('/api/sessions/revoke-all',{method:'POST'});showLogin();}catch(err){toast(err.message,true);e.target.disabled=false;}});
 if($('#security-form'))$('#security-form').addEventListener('submit',async e=>{e.preventDefault();const btn=$('[type=submit]',e.target);btn.disabled=true;const f=new FormData(e.target),next=clone();Object.assign(next,{mode:f.get('mode'),paranoia:Number(f.get('paranoia')),threshold:Number(f.get('threshold')),maxBodyBytes:Number(f.get('maxBodyKiB'))*1024,rateLimit:Number(f.get('rateLimit')),responseInspection:f.has('responseInspection'),denyCIDRs:lines(f.get('denyCIDRs')),allowCIDRs:lines(f.get('allowCIDRs'))});try{await saveConfig(next);}catch(err){toast(err.message,true);}finally{btn.disabled=false;}});
 if($('#event-search'))$('#event-search').addEventListener('input',e=>{state.query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(updateEventTable,120);});
 if($('#event-filter'))$('#event-filter').addEventListener('change',e=>{state.action=e.target.value;updateEventTable();});
 if($('#export-config'))$('#export-config').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state.config,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bastion-config.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 if($('#import-config'))$('#import-config').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1048576)throw new Error('File is larger than 1 MiB.');const config=JSON.parse(await file.text());if(!Array.isArray(config.routes)||!Array.isArray(config.rules))throw new Error('Not a valid Bastion configuration.');openDialog('Import configuration',`<div class="info warning">Replaces all current settings with ${config.routes.length} Proxy Hosts and ${config.rules.length} custom rules. Full validation is performed before activation.</div>`,async()=>{await saveConfig(config);},'Import');}catch(err){toast(err.message,true);}e.target.value='';});
}
let dialogSubmit=null;
function openDialog(title,fields,onSubmit,button='Save'){state.revision=state.config.revision;$('#dialog-title').textContent=title;$('#dialog-fields').innerHTML=fields;$('#dialog-error').textContent='';$('#dialog-save').textContent=button;$('#dialog-save').hidden=!onSubmit;dialogSubmit=onSubmit;$('#editor').showModal();}
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#editor').close();
$('#editor-form').addEventListener('submit',async e=>{e.preventDefault();if(!dialogSubmit)return;const btn=$('#dialog-save');btn.disabled=true;$('#dialog-error').textContent='';try{if(state.config.revision!==state.revision)throw new Error('Configuration changed. Please reopen the dialog.');await dialogSubmit(new FormData(e.target));$('#editor').close();render();}catch(err){$('#dialog-error').textContent=err.message;}finally{btn.disabled=false;}});
function routeEditor(id){const r=state.config.routes.find(r=>r.id===id)||{id:crypto.randomUUID(),name:'',host:'',path:'/',upstreams:[],enabled:true,preserveHost:true,excludedRuleIds:[]};openDialog(id?'Edit proxy host':'Connect new application',`<div class="field"><label for="route-name">Application name</label><input id="route-name" name="name" required maxlength="100" value="${esc(r.name)}" placeholder="e.g. Nextcloud"></div><div class="form-grid"><div class="field"><label for="route-host">Domain</label><input id="route-host" name="host" required maxlength="253" value="${esc(r.host)}" placeholder="cloud.example.com"></div><div class="field"><label for="route-path">Path prefix</label><input id="route-path" name="path" required value="${esc(r.path)}" placeholder="/"></div></div><div class="field"><label for="route-upstreams">Backend addresses <small>· one per line</small></label><textarea id="route-upstreams" name="upstreams" required placeholder="http://10.0.0.20:8080">${esc(r.upstreams.join('\n'))}</textarea><p class="field-help">HTTP(S) origin without a subpath. Multiple backends use round-robin while healthy; failed targets cool down for later requests. Request bodies are never retried.</p></div><div class="field"><label for="excluded">Excluded CRS rule IDs <small>· optional</small></label><input id="excluded" name="excludedRuleIds" value="${esc(r.excludedRuleIds.join(', '))}" placeholder="e.g. 920350"><p class="field-help">Use targeted exclusions only for confirmed false positives.</p></div><label class="check"><input type="checkbox" name="oidcProtected" ${r.oidcProtected?'checked':''}> Require OIDC login for this proxy host</label><p class="field-help">First enable proxy login on the OIDC page and restart Bastion.</p><label class="check"><input type="checkbox" name="preserveHost" ${r.preserveHost?'checked':''}> Forward the original Host header to the backend</label><div class="separator"></div><h3>Route security policy</h3><p class="field-help">Zero or inherit leaves the global policy in effect. Body and rate limits may only be stricter than global limits.</p><div class="form-grid"><div class="field"><label for="route-wafMode">WAF mode</label><select id="route-wafMode" name="wafMode"><option value="inherit" ${!r.wafMode||r.wafMode==='inherit'?'selected':''}>Inherit global</option><option value="blocking" ${r.wafMode==='blocking'?'selected':''}>Blocking</option><option value="detection" ${r.wafMode==='detection'?'selected':''}>Detection</option></select></div><div class="field"><label for="route-paranoia">Paranoia override</label><input id="route-paranoia" name="paranoia" type="number" min="0" max="4" value="${r.paranoia||0}"></div></div><div class="form-grid"><div class="field"><label for="route-threshold">Anomaly threshold override</label><input id="route-threshold" name="anomalyThreshold" type="number" min="0" max="100" value="${r.anomalyThreshold||0}"></div><div class="field"><label for="route-rateLimit">Requests/minute override</label><input id="route-rateLimit" name="rateLimit" type="number" min="0" max="100000" value="${r.rateLimit||0}"></div></div><div class="form-grid"><div class="field"><label for="route-maxBodyBytes">Maximum body (KiB)</label><input id="route-maxBodyBytes" name="maxBodyKiB" type="number" min="0" max="32768" value="${r.maxBodyBytes?Math.round(r.maxBodyBytes/1024):0}"></div><div class="field"><label for="route-methods">Allowed methods</label><input id="route-methods" name="allowedMethods" value="${esc((r.allowedMethods||[]).join(', '))}" placeholder="GET, POST"></div></div><div class="field"><label for="route-contentTypes">Allowed request Content-Types</label><input id="route-contentTypes" name="allowedContentTypes" value="${esc((r.allowedContentTypes||[]).join(', '))}" placeholder="application/json, multipart/form-data"><label class="check"><input type="checkbox" name="requireContentType" ${r.requireContentType?'checked':''}> Require a valid Content-Type on body methods</label><p class="field-help">Rejects unexpected or malformed body formats before forwarding.</p></div><label class="check"><input type="checkbox" name="securityHeaders" ${r.securityHeaders?'checked':''}> Add browser security response headers</label><div class="field"><label for="route-botPatterns">Denied bot user-agent patterns</label><textarea id="route-botPatterns" name="botDenyPatterns" rows="3" placeholder="curl">${esc((r.botDenyPatterns||[]).join('\n'))}</textarea><p class="field-help">Case-insensitive regular expressions, up to 32 patterns.</p></div><label class="check"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}> Enable route</label>`,async f=>{const next=clone(),updated={...r,name:f.get('name').trim(),host:f.get('host').trim().toLowerCase(),path:f.get('path').trim(),upstreams:lines(f.get('upstreams')),excludedRuleIds:lines(f.get('excludedRuleIds')).map(Number),preserveHost:f.has('preserveHost'),oidcProtected:f.has('oidcProtected'),enabled:f.has('enabled'),wafMode:f.get('wafMode'),paranoia:Number(f.get('paranoia'))||0,anomalyThreshold:Number(f.get('anomalyThreshold'))||0,rateLimit:Number(f.get('rateLimit'))||0,maxBodyBytes:(Number(f.get('maxBodyKiB'))||0)*1024,allowedMethods:lines(f.get('allowedMethods')).map(x=>x.toUpperCase()),allowedContentTypes:lines(f.get('allowedContentTypes')).map(x=>x.toLowerCase()),requireContentType:f.has('requireContentType'),securityHeaders:f.has('securityHeaders'),botDenyPatterns:lines(f.get('botDenyPatterns'))};const idx=next.routes.findIndex(x=>x.id===r.id);if(idx>=0)next.routes[idx]=updated;else next.routes.push(updated);await saveConfig(next);});}
function ruleEditor(id){const r=state.config.rules.find(r=>r.id===id)||{id:crypto.randomUUID(),name:'',category:'A05',field:'query',value:'',action:'block',enabled:true};openDialog(id?'Edit rule':'Create custom rule',`<div class="field"><label for="rule-name">Name</label><input id="rule-name" name="name" required maxlength="100" value="${esc(r.name)}" placeholder="Block suspicious query"></div><div class="form-grid"><div class="field"><label for="rule-category">OWASP Top 10:2025 category</label><select id="rule-category" name="category"><option value="">General gateway rule</option>${['A01','A02','A03','A04','A05','A06','A07','A08','A09','A10'].map(v=>`<option value="${v}" ${r.category===v?'selected':''}>${v} · ${esc(owaspNames[v])}</option>`).join('')}</select></div><div class="field"><label for="rule-field">Field</label><select id="rule-field" name="field">${['path','query','header','user-agent','method','body'].map(v=>`<option ${r.field===v?'selected':''}>${v}</option>`).join('')}</select></div></div><p class="field-help">Literal matching is bounded and case-insensitive. OWASP CRS remains the primary detector for injection, XSS, traversal, and command injection.</p><div class="form-grid"><div class="field"><label for="rule-action">Action</label><select id="rule-action" name="action"><option value="block" ${r.action==='block'?'selected':''}>Block</option><option value="log" ${r.action==='log'?'selected':''}>Log</option></select></div><div class="field"><label for="rule-value">Contains</label><input id="rule-value" name="value" required maxlength="256" value="${esc(r.value)}" placeholder="' union select"></div></div><label class="check"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}> Enable rule</label>`,async f=>{const next=clone(),updated={...r,name:f.get('name').trim(),category:f.get('category'),field:f.get('field'),value:f.get('value'),action:f.get('action'),enabled:f.has('enabled')};const idx=next.rules.findIndex(x=>x.id===r.id);if(idx>=0)next.rules[idx]=updated;else next.rules.push(updated);await saveConfig(next);});}
function detail(id){const e=state.events.find(e=>e.id===id);if(!e)return;openDialog('Request details',`<dl class="detail-list">${[['Request ID',e.id],['Time',new Date(e.time).toLocaleString('en-US')],['Client-IP',e.client],['Domain',e.host],['Route',e.route||'—'],['Method',e.method],['Path',e.path],['Status',e.status],['Duration',`${e.duration.toFixed(2)} ms`],['Reason',e.reason||'No rule match'],['CRS rules',e.ruleIds.join(', ')||'—']].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="info">Payloads and query strings are not logged to protect sensitive data.</div>`,null);}
$('#main').addEventListener('click',async e=>{const el=e.target.closest('button,[data-event]');if(!el)return;try{if(el.hasAttribute('data-add-route'))routeEditor();if(el.dataset.editRoute)routeEditor(el.dataset.editRoute);if(el.hasAttribute('data-add-rule'))ruleEditor();if(el.dataset.editRule)ruleEditor(el.dataset.editRule);if(el.dataset.event)detail(el.dataset.event);if(el.dataset.toggleRoute){el.disabled=true;const next=clone(),r=next.routes.find(r=>r.id===el.dataset.toggleRoute);r.enabled=!r.enabled;await saveConfig(next);render();}for(const [key,collection,label] of [['deleteRoute','routes','Proxy Host'],['deleteRule','rules','Rule']]){if(el.dataset[key]){const id=el.dataset[key],item=state.config[collection].find(r=>r.id===id);openDialog(`${label} delete?`,`<p>„${esc(item.name)}“ will be removed from the configuration.</p>`,async()=>{const next=clone();next[collection]=next[collection].filter(r=>r.id!==id);await saveConfig(next);},'Delete');}}}catch(err){toast(err.message,true);el.disabled=false;}});
$('#main').addEventListener('keydown',e=>{if(e.target.matches('[data-event]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();detail(e.target.dataset.event);}});
async function poll(){if(!state.ready||document.hidden||state.polling)return;state.polling=true;try{const [status,events]=await Promise.all([api('/api/status'),api('/api/events')]);if(!state.ready)return;state.status=status;state.events=events;$('#connection').classList.remove('offline');$('#connection').innerHTML='<span class="status-dot"></span> Connected';$('#updated').textContent=`Updated at ${time(Date.now())}`;if(state.page==='overview'&&!$('#editor').open)render();else updateEventTable();}catch(err){$('#connection').classList.add('offline');$('#connection').innerHTML='<span class="status-dot"></span> Connection interrupted';}finally{state.polling=false;}}
setInterval(poll,5000);
(async()=>{try{const s=await api('/api/session');state.csrf=s.csrf;await start();}catch{showLogin();}})();
